<?php
require_once '../includes/funcoes.php';exigir_admin();$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT p.*,u.nome cliente,u.email FROM pedidos p JOIN usuarios u ON u.id=p.usuario_id WHERE p.id=?");$s->execute([$id]);$p=$s->fetch();if(!$p)exit('Pedido não encontrado.');if($_SERVER['REQUEST_METHOD']==='POST'){$status=$_POST['status'];if(in_array($status,['Pendente','Em preparação','Enviado','Concluído','Cancelado'],true)){$pdo->prepare("UPDATE pedidos SET status=? WHERE id=?")->execute([$status,$id]);log_acao("Status do pedido #$id alterado para $status");header("Location: pedido_detalhe.php?id=$id");exit;}}
$s=$pdo->prepare("SELECT i.*,pr.nome FROM itens_pedido i JOIN produtos pr ON pr.id=i.produto_id WHERE i.pedido_id=?");$s->execute([$id]);$itens=$s->fetchAll();$titulo='Detalhe do pedido';require '../includes/header.php';?>
<div class="admin-shell"><?php require '_menu.php';?><section><div class="panel"><h1>Pedido #<?=$id?></h1><p>Cliente: <?=e($p['cliente'])?> · <?=e($p['email'])?></p><p>Endereço: <?=e($p['endereco'])?></p><form method="post" class="row g-2 mb-4"><div class="col-md-5"><select class="form-select" name="status"><?php foreach(['Pendente','Em preparação','Enviado','Concluído','Cancelado'] as $st):?><option <?=$p['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></div><div class="col-md-3"><button class="btn btn-lumia">Atualizar status</button></div></form><table class="table"><thead><tr><th>Produto</th><th>Quantidade</th><th>Preço</th></tr></thead><tbody><?php foreach($itens as $i):?><tr><td><?=e($i['nome'])?></td><td><?=$i['quantidade']?></td><td><?=preco($i['preco_unitario'])?></td></tr><?php endforeach;?></tbody></table><h3 class="text-end"><?=preco($p['total'])?></h3></div></section></div><?php require '../includes/footer.php';?>
